alter table public.app_users add column if not exists commission_rate numeric(7,4) not null default 0 check (commission_rate>=0 and commission_rate<=100);
create table if not exists public.employee_commission_earnings(id uuid primary key default gen_random_uuid(),ledger_id uuid not null unique references public.payments_ledger(id) on delete restrict,approval_request_id uuid not null unique references public.payment_approval_requests(id) on delete restrict,employee_email text not null,gross_amount numeric(14,2) not null check(gross_amount>=0),commission_rate numeric(7,4) not null check(commission_rate>=0 and commission_rate<=100),earned_amount numeric(14,2) not null check(earned_amount>=0),status text not null default 'Earned' check(status in ('Earned','Adjusted','Reversed')),approved_by_email text not null,approved_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists employee_commission_email_approved_idx on public.employee_commission_earnings(lower(employee_email),approved_at desc);
alter table public.employee_commission_earnings enable row level security;
drop policy if exists employee_commission_select_own_or_admin on public.employee_commission_earnings;
create policy employee_commission_select_own_or_admin on public.employee_commission_earnings for select to authenticated using(lower(employee_email)=lower(coalesce(auth.jwt()->>'email','')) or lower(coalesce(auth.jwt()->>'email',''))='afinch2678@gmail.com');
create or replace function public.cpcm_set_employee_commission(target_email text,rate_percent numeric) returns jsonb language plpgsql security invoker set search_path=public as $$ declare updated_count integer; begin if lower(coalesce(auth.jwt()->>'email',''))<>'afinch2678@gmail.com' then raise exception 'Admin only'; end if; if rate_percent<0 or rate_percent>100 then raise exception 'Commission rate must be between 0 and 100'; end if; update public.app_users set commission_rate=round(rate_percent,4),updated_at=now() where lower(email)=lower(target_email); get diagnostics updated_count=row_count; if updated_count<>1 then raise exception 'Employee not found'; end if; return jsonb_build_object('ok',true,'employee_email',lower(target_email),'commission_rate',round(rate_percent,4)); end $$;
create or replace function public.cpcm_record_approved_commission(target_approval_request_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare req public.payment_approval_requests%rowtype; led public.payments_ledger%rowtype; rate numeric; eid uuid; earned numeric; actor text:=lower(coalesce(auth.jwt()->>'email','')); begin if actor<>'afinch2678@gmail.com' then raise exception 'Admin only'; end if; select * into req from public.payment_approval_requests where id=target_approval_request_id for update; if not found then raise exception 'Approval request not found'; end if; if lower(coalesce(req.status,'')) not in ('approved','completed','paid') or req.ledger_id is null or req.reviewed_by_email is null then raise exception 'Payment has not been approved and finalized by Admin'; end if; if lower(req.reviewed_by_email)<>actor then raise exception 'Commission requires the Admin approval actor'; end if; select * into led from public.payments_ledger where id=req.ledger_id; if not found then raise exception 'Approved ledger entry not found'; end if; if lower(coalesce(led.status,'')) not in ('completed','paid','settled','processed','success') or lower(coalesce(led.gateway_provider,''))<>'nmi' or coalesce(led.gateway_transaction_id,'')='' then raise exception 'Ledger is not a finalized approved NMI payment'; end if; select commission_rate into rate from public.app_users where lower(email)=lower(req.requested_by_email) and coalesce(is_active,true)=true; if not found then raise exception 'Employee not found'; end if; earned:=round(coalesce(led.amount,led.payment_amount,0)*rate/100,2); insert into public.employee_commission_earnings(ledger_id,approval_request_id,employee_email,gross_amount,commission_rate,earned_amount,status,approved_by_email,approved_at) values(led.id,req.id,lower(req.requested_by_email),coalesce(led.amount,led.payment_amount,0),rate,earned,'Earned',lower(req.reviewed_by_email),coalesce(req.reviewed_at,led.paid_at,led.created_at,now())) on conflict(approval_request_id) do nothing returning id into eid; if eid is null then select id into eid from public.employee_commission_earnings where approval_request_id=req.id; end if; return jsonb_build_object('ok',true,'earning_id',eid,'employee_email',lower(req.requested_by_email),'gross_amount',coalesce(led.amount,led.payment_amount,0),'commission_rate',rate,'earned_amount',earned); end $$;
revoke all on public.employee_commission_earnings from anon; grant select on public.employee_commission_earnings to authenticated;
revoke execute on function public.cpcm_set_employee_commission(text,numeric) from public,anon; revoke execute on function public.cpcm_record_approved_commission(uuid) from public,anon; grant execute on function public.cpcm_set_employee_commission(text,numeric) to authenticated; grant execute on function public.cpcm_record_approved_commission(uuid) to authenticated;
